-- GENERATED by src/mk.py. records_nov22 Phase B test 05 B8 run history export (manager-only).
-- ONE statement (a DO block). Runs apply 01..05 (each safe to run twice), exercises it, then ALWAYS raises
-- 'RESULT: n pass, m fail ...' so the whole block is rolled back and NOTHING is kept (throwaway users/company included).
-- Expect an ERROR whose message starts with RESULT: and says 0 fail.
do $T$
declare
  q_tag text; q_ow uuid; q_fm uuid; q_pm uuid; q_xo uuid; q_co uuid; q_co2 uuid; q_day date; q_t0 timestamptz := clock_timestamp();
  q_b64 text; q_sha text; q_b64b text; q_shab text;
  q_r jsonb; q_x text; q_n integer; q_m integer; q_id uuid; q_snap jsonb; q_rec jsonb;
  q_pass integer; q_fail integer; q_fails text; q_notes text := '';
  q_run uuid; q_entry text; q_i integer;
begin
  -- test helpers (temporary, gone with the rollback)
  create temp table q_chk (i serial, name text, ok boolean, got text) on commit drop;
  create or replace function pg_temp.q_ck(p_name text, p_ok boolean, p_got text) returns void language sql as $q$
    insert into pg_temp.q_chk (name, ok, got) values (p_name, coalesce(p_ok, false), p_got) $q$;
  -- "signed in as": the JWT claims PostgREST sets, and the role the app's requests run as (authenticated)
  create or replace function pg_temp.q_as(p_uid uuid) returns void language plpgsql as $q$
  begin
    perform set_config('request.jwt.claim.sub', '', true);
    if p_uid is null then perform set_config('request.jwt.claims', '{"role":"anon"}', true); return; end if;
    perform set_config('request.jwt.claims', jsonb_build_object('sub', p_uid, 'role', 'authenticated', 'aal', 'aal1')::text, true);
    if current_setting('pbrec.as_auth', true) = '1' then set local role authenticated; end if;
  end $q$;
  -- ===== apply 01 =====
-- records_nov22 Phase B, 01: helper schema pb_stage (needed by 02 B3; 03-05 don't call it but 03 checks 02 is in).
-- Plain SQL, valid as-is or pasted inside a DO block (no top-level SELECT, no begin/commit). Safe to run many times.
-- pb_stage.guard(tag, function, md5): refuses (so the whole migration rolls back) when the live text of a function we
--   replace is not the one read on Nov 22 2026; when it matches, the live text is saved in pb_stage.fn_backup first, so
--   the undo puts back the exact text that was live (pb_stage.restore(tag)). Second run of a migration: the backup row
--   is there, so it goes through again.
-- pb_stage.patch_fn(function, old, new [, tag]): replaces ONE exact piece of a live function and recreates it; refuses
--   when the piece is there 0 or 2+ times. With a tag, saves the live text for restore first.
-- pb_stage.count_in_fn(function, piece): read-only count of the same thing.
-- Nothing here is reachable from the API (schema and functions closed to anon/authenticated).
create schema if not exists pb_stage;
revoke all on schema pb_stage from public;
revoke all on schema pb_stage from anon, authenticated;
create table if not exists pb_stage.fn_backup (
  tag      text not null,
  sig      text not null,
  def      text not null,
  md5      text not null,
  saved_at timestamptz not null default now(),
  primary key (tag, sig)
);
alter table pb_stage.fn_backup enable row level security;
revoke all on table pb_stage.fn_backup from public;
revoke all on table pb_stage.fn_backup from anon, authenticated;

create or replace function pb_stage.guard(p_tag text, p_sig text, p_md5 text) returns void
language plpgsql set search_path to '' as $f$
declare v_def text; v_md5 text;
begin
  v_def := pg_get_functiondef(p_sig::regprocedure);
  v_md5 := md5(v_def);
  if v_md5 = p_md5 then
    insert into pb_stage.fn_backup (tag, sig, def, md5) values (p_tag, p_sig, v_def, v_md5) on conflict (tag, sig) do nothing;
    return;
  end if;
  if exists (select 1 from pb_stage.fn_backup b where b.tag = p_tag and b.sig = p_sig) then return; end if; -- this migration ran before
  -- throwaway local test database only (its stand-in functions are not the live text)
  if current_setting('pb_stage.guard', true) = 'skip-local-test' then
    insert into pb_stage.fn_backup (tag, sig, def, md5) values (p_tag, p_sig, v_def, v_md5) on conflict (tag, sig) do nothing;
    return;
  end if;
  raise exception 'pb_stage: % changed on live since Nov 22 2026 (md5 %, expected %). Nothing was applied. Re-read it and rebase this migration.', p_sig, v_md5, p_md5;
end $f$;

create or replace function pb_stage.restore(p_tag text) returns integer
language plpgsql set search_path to '' as $f$
declare r record; n integer := 0;
begin
  for r in select b.sig, b.def from pb_stage.fn_backup b where b.tag = p_tag order by b.sig loop
    execute r.def; n := n + 1;
  end loop;
  delete from pb_stage.fn_backup where tag = p_tag;
  return n;
end $f$;

create or replace function pb_stage.count_in_fn(p_fn regprocedure, p_old text) returns integer
language sql stable set search_path to '' as $f$
  select (length(pg_get_functiondef(p_fn)) - length(replace(pg_get_functiondef(p_fn), p_old, ''))) / greatest(length(p_old), 1)
$f$;

create or replace function pb_stage.patch_fn(p_fn regprocedure, p_old text, p_new text, p_tag text default null) returns void
language plpgsql set search_path to '' as $f$
declare d text := pg_get_functiondef(p_fn); n integer;
begin
  if coalesce(p_old, '') = '' then raise exception 'patch_fn %: empty piece', p_fn; end if;
  n := (length(d) - length(replace(d, p_old, ''))) / length(p_old);
  if n <> 1 then raise exception 'patch_fn %: expected the piece once, found % times: %', p_fn, n, left(p_old, 80); end if;
  if p_tag is not null then
    insert into pb_stage.fn_backup (tag, sig, def, md5) values (p_tag, p_fn::text, d, md5(d)) on conflict (tag, sig) do nothing;
  end if;
  execute replace(d, p_old, p_new);
end $f$;

revoke all on function pb_stage.guard(text, text, text) from public;
revoke all on function pb_stage.guard(text, text, text) from anon, authenticated;
revoke all on function pb_stage.restore(text) from public;
revoke all on function pb_stage.restore(text) from anon, authenticated;
revoke all on function pb_stage.count_in_fn(regprocedure, text) from public;
revoke all on function pb_stage.count_in_fn(regprocedure, text) from anon, authenticated;
revoke all on function pb_stage.patch_fn(regprocedure, text, text, text) from public;
revoke all on function pb_stage.patch_fn(regprocedure, text, text, text) from anon, authenticated;

  -- ===== apply 02 =====
-- records_nov22 Phase B, 02 (B3): keep the open permit's "first seen by the server" proof when the permit closes.
-- Before: pb_safety.drop_open_on_close (AFTER INSERT on pb_safety.permits = the first close-out backup) deletes the
-- pb_safety.open_permits row, and with it first_saved_at (when the server first had the open permit), saves (how many
-- times it was saved while open) and the last open snapshot's fingerprint.
-- After: those are copied onto the permit first (5 new nullable columns), then the open row is dropped as before.
-- open_clock_ahead_s = phone clock minus server clock at the last open save, only when the open snapshot carries phoneAt
-- (r17.16 app part b3_open_phoneat.py adds it; r17.15 phones don't, so it stays null for them). A bad phoneAt never
-- stops the rest being copied, and nothing here can make a close-out backup fail (each step has its own exception
-- handler, like the live function).
-- The delete is wrapped in pb.allow_record_delete = 'on' (transaction-local, reset right after) so 03 B9's no-delete
-- guard on open_permits lets only this through. Before 03 is applied the setting is simply unused.
-- Needs 01. Plain SQL, DO-block safe. Safe to run twice. Undo: 99_undo_02.sql (exact live text back from pb_stage).
do $g$ begin
  perform pb_stage.guard('records_b3', 'pb_safety.drop_open_on_close()', '06bf4e0e338276c9d73f8a5e6a0879d3');
end $g$;

alter table pb_safety.permits
  add column if not exists open_first_saved_at timestamptz,
  add column if not exists open_last_saved_at timestamptz,
  add column if not exists open_saves integer,
  add column if not exists open_last_sha256 text,
  add column if not exists open_clock_ahead_s integer;

create or replace function pb_safety.drop_open_on_close() returns trigger
language plpgsql security definer set search_path to '' as $f$
declare o pb_safety.open_permits%rowtype; v_ahead integer;
begin
  -- records_nov22 B3: keep the open permit's proof on the permit before the open row goes
  begin
    select * into o from pb_safety.open_permits x where x.user_id = new.user_id and x.client_permit_id = new.client_permit_id;
    if found then
      begin
        if coalesce(o.snapshot->>'phoneAt', '') ~ '^\d{4}-\d\d-\d\dT\d\d:\d\d' then
          v_ahead := greatest(-31536000, least(31536000, round(extract(epoch from ((o.snapshot->>'phoneAt')::timestamptz - o.saved_at)))))::integer;
        end if;
      exception when others then v_ahead := null;
      end;
      update pb_safety.permits p
         set open_first_saved_at = o.first_saved_at, open_last_saved_at = o.saved_at, open_saves = o.saves,
             open_last_sha256 = o.record_sha256, open_clock_ahead_s = v_ahead
       where p.id = new.id;
    end if;
  exception when others then
    raise log 'pb_safety.drop_open_on_close: proof not copied (%)', sqlstate; perform pb_prod.note_error('pb_safety.drop_open_on_close: proof not copied (%)', sqlstate, sqlerrm);
  end;
  begin
    perform set_config('pb.allow_record_delete', 'on', true); -- records_nov22 B9: the open_permits no-delete guard lets only this through
    delete from pb_safety.open_permits where user_id = new.user_id and client_permit_id = new.client_permit_id;
    perform set_config('pb.allow_record_delete', '', true);
  exception when others then
    perform set_config('pb.allow_record_delete', '', true);
    raise log 'pb_safety.drop_open_on_close: skipped (%)', sqlstate; perform pb_prod.note_error('pb_safety.drop_open_on_close: skipped (%)', sqlstate, sqlerrm);
  end;
  return null;
end $f$;

  -- ===== apply 03 =====
-- records_nov22 Phase B, 03 (B9): the 7 tables the r16.80 admin log missed get it, plus guards so their history can't
-- be changed quietly from the console / SQL editor / service key.
--   pb_daily.events         only the review fields may change (status, reviewed_at, reviewed_by, review_rev,
--                           changed_after_review) and superseded_at once (null -> a time); no delete
--   pb_daily.event_photos   insert only          pb_daily.report_photos  insert only; FK to reports no longer ON DELETE CASCADE
--   pb_daily.event_reviews  insert only          pb_tickets.photos       insert only
--   pb_prod.talks_given     no delete (updates are the app's edit path; 04 B5 keeps every version)
--   pb_safety.open_permits  no delete (updates are the app's open-save path) except the close-out drop (02 B3 sets
--                           pb.allow_record_delete = 'on' for that one statement)
--   all 7                   no TRUNCATE; zz_pb_audit (pb_audit.direct_write) like the other record tables
-- Read on live Nov 22 2026: none of the 7 had any of these triggers. App writers checked (exact SQL in the live functions):
-- pb_daily.events_store (INSERT events/event_photos/event_reviews; UPDATE events SET superseded_at WHERE superseded_at IS NULL),
-- pb_daily_event_review (UPDATE events SET status, reviewed_at, reviewed_by, review_rev, changed_after_review; INSERT event_reviews),
-- pb_daily_event_photo_put / pb_daily_report_photo_put / pb_ticket_save (INSERT ... ON CONFLICT DO NOTHING),
-- pb_talk_give (INSERT / UPDATE talks_given), pb_permit_open_put (INSERT ... ON CONFLICT DO UPDATE open_permits),
-- pb_safety.drop_open_on_close (DELETE open_permits). No other function, cron job or edge function deletes or updates them.
-- A future owner flow that must delete (delete-job) sets pb.allow_record_delete = 'on' for its own transaction, like
-- pb.allow_permit_delete today. Error raised: 'pb:history_is_permanent' (the app never sees it: no app path is refused).
-- Needs 02 (refuses otherwise). Plain SQL, DO-block safe. Safe to run twice. Undo: 99_undo_03.sql.
do $c$ begin
  if position('pb.allow_record_delete' in pg_get_functiondef('pb_safety.drop_open_on_close()'::regprocedure)) = 0 then
    raise exception 'records B9: apply 02_b3.apply.sql first (the close-out drop of open permits must set pb.allow_record_delete). Nothing was applied.';
  end if;
end $c$;

create or replace function pb_daily.record_delete_guard() returns trigger
language plpgsql set search_path to '' as $f$
begin
  if tg_op = 'DELETE' and coalesce(current_setting('pb.allow_record_delete', true), '') = 'on' then return old; end if;
  raise exception 'pb:history_is_permanent';
end $f$;

create or replace function pb_daily.events_guard() returns trigger
language plpgsql set search_path to '' as $f$
begin
  if tg_op = 'DELETE' then
    if coalesce(current_setting('pb.allow_record_delete', true), '') = 'on' then return old; end if;
    raise exception 'pb:history_is_permanent';
  end if;
  if (new.id, new.company_id, new.job_key, new.job_number, new.report_id, new.client_event_id, new.work_date, new.kind, new.reason, new.detail,
      new.hours, new.crew_size, new.equipment, new.photo_count, new.photos_signed, new.fp, new.same_as_prev, new.created_by, new.foreman_name, new.created_at)
     is distinct from
     (old.id, old.company_id, old.job_key, old.job_number, old.report_id, old.client_event_id, old.work_date, old.kind, old.reason, old.detail,
      old.hours, old.crew_size, old.equipment, old.photo_count, old.photos_signed, old.fp, old.same_as_prev, old.created_by, old.foreman_name, old.created_at) then
    raise exception 'pb:history_is_permanent';
  end if;
  if old.superseded_at is not null and new.superseded_at is distinct from old.superseded_at then raise exception 'pb:history_is_permanent'; end if;
  return new;
end $f$;

revoke all on function pb_daily.record_delete_guard() from public;
revoke all on function pb_daily.record_delete_guard() from anon, authenticated;
revoke all on function pb_daily.events_guard() from public;
revoke all on function pb_daily.events_guard() from anon, authenticated;

