-- a report deleted in the console no longer takes its photos with it (was ON DELETE CASCADE): the delete is refused
alter table pb_daily.report_photos drop constraint if exists report_photos_report_id_fkey;
alter table pb_daily.report_photos add constraint report_photos_report_id_fkey foreign key (report_id) references pb_daily.reports(id) not valid;
alter table pb_daily.report_photos validate constraint report_photos_report_id_fkey;

-- no TRUNCATE, and the admin log (every write not from a signed-in app user or the app's scheduled jobs)
do $d$ declare t text; n text; begin
  foreach t in array array['pb_daily.events', 'pb_daily.event_photos', 'pb_daily.report_photos', 'pb_daily.event_reviews',
                           'pb_prod.talks_given', 'pb_safety.open_permits', 'pb_tickets.photos'] loop
    n := split_part(t, '.', 2) || '_no_truncate';
    if t = 'pb_tickets.photos' then n := 'ticket_photos_no_truncate'; end if;
    execute format('drop trigger if exists %I on %s', n, t);
    execute format('create trigger %I before truncate on %s for each statement execute function pb_daily.record_delete_guard()', n, t);
    execute format('drop trigger if exists zz_pb_audit on %s', t);
    execute format('create trigger zz_pb_audit after insert or delete or update on %s for each row execute function pb_audit.direct_write()', t);
  end loop;
end $d$;

  -- ===== apply 04 =====
-- records_nov22 Phase B, 04 (B5): toolbox talks keep every version.
-- Before: pb_talk_give UPDATEs pb_prod.talks_given in place (version + 1); the earlier attendees / date / title are gone.
-- After: a trigger copies every saved row (insert and each update, with the server time and an md5 of the row) into
-- pb_prod.talk_versions, which nobody can change, delete or truncate. Keyed (talk, version, md5), so a console edit that
-- doesn't bump the version is still kept as its own row. The talks there now are copied in as their current version
-- (live Nov 22 2026: 0 rows). Not reachable from the API (RLS on, no policies, no grants); read later through
-- security-definer functions ("entered on" / version history in the app: follow-up, not here).
-- Independent of 01-03. Plain SQL, DO-block safe. Safe to run twice. Undo: 99_undo_04.sql (stops copying; the versions stay).
create table if not exists pb_prod.talk_versions (
  id         bigint generated always as identity primary key,
  talk_id    uuid not null,
  company_id uuid not null,
  version    integer not null,
  row_md5    text not null,
  row_data   jsonb not null,
  saved_at   timestamptz not null default now(),
  unique (talk_id, version, row_md5)
);
alter table pb_prod.talk_versions enable row level security;
revoke all on table pb_prod.talk_versions from public;
revoke all on table pb_prod.talk_versions from anon, authenticated;

create or replace function pb_prod.talk_version_keep() returns trigger
language plpgsql security definer set search_path to '' as $f$
begin
  insert into pb_prod.talk_versions (talk_id, company_id, version, row_md5, row_data)
    values (new.id, new.company_id, new.version, md5(to_jsonb(new)::text), to_jsonb(new))
    on conflict (talk_id, version, row_md5) do nothing;
  return null;
end $f$;
revoke all on function pb_prod.talk_version_keep() from public;
revoke all on function pb_prod.talk_version_keep() from anon, authenticated;

drop trigger if exists talks_given_versions on pb_prod.talks_given;
create trigger talks_given_versions after insert or update on pb_prod.talks_given for each row execute function pb_prod.talk_version_keep();
drop trigger if exists talk_versions_locked on pb_prod.talk_versions;
create trigger talk_versions_locked before update or delete on pb_prod.talk_versions for each row execute function pb_prod.versions_locked();
drop trigger if exists talk_versions_no_truncate on pb_prod.talk_versions;
create trigger talk_versions_no_truncate before truncate on pb_prod.talk_versions for each statement execute function pb_prod.versions_locked();
drop trigger if exists zz_pb_audit on pb_prod.talk_versions;
create trigger zz_pb_audit after insert or delete or update on pb_prod.talk_versions for each row execute function pb_audit.direct_write();

insert into pb_prod.talk_versions (talk_id, company_id, version, row_md5, row_data, saved_at)
  select tg.id, tg.company_id, tg.version, md5(to_jsonb(tg)::text), to_jsonb(tg), tg.updated_at from pb_prod.talks_given tg
  on conflict (talk_id, version, row_md5) do nothing;

  -- ===== apply 05 =====
-- records_nov22 Phase B, 05 (B8): a run's whole history for Export for Records. NEW function only; changes no table
-- and no existing function. Manager-only: the company account (owner) or a listed manager of the run's company
-- (pb_prod.managed_company, the same test the office screens use). Returns every stored version (server time, md5,
-- size), the run's events (sent back, approved, removed + reason, restored) and the office's setup changes.
-- Version records are full run records (photos are never in them; the app refuses data:image): the newest 40 versions
-- carry the record itself as long as they add up to 20 MB or less; older ones are listed with their md5 only.
-- Errors (raised, like the other run RPCs): pb:signed_out, pb:wrong_account, pb:not_found, pb:not_company_account.
-- r17.15 phones never call it. r17.16 (b8_export_versions.py) calls it from Export for Records and, on any error, says
-- so in the manifest and exports as before.
-- Independent of 01-04. Plain SQL, DO-block safe. Safe to run twice. Undo: 99_undo_05.sql.
create or replace function public.pb_prod_run_versions(p_run_id uuid, p_expect_uid uuid) returns jsonb
language plpgsql stable security definer set search_path to '' as $f$
declare v_uid uuid := auth.uid(); r pb_prod.run_records%rowtype;
begin
  if v_uid is null then raise exception 'pb:signed_out'; end if;
  if p_expect_uid is null or v_uid <> p_expect_uid then raise exception 'pb:wrong_account'; end if;
  if p_run_id is null then raise exception 'pb:not_found'; end if;
  select * into r from pb_prod.run_records x where x.id = p_run_id;
  if not found then raise exception 'pb:not_found'; end if;
  if not coalesce(pb_prod.managed_company(v_uid) = r.company_id, false) then raise exception 'pb:not_company_account'; end if;
  return jsonb_build_object('ok', true, 'run_id', r.id, 'entry_id', r.entry_id, 'current_version', r.version, 'server_at', now(),
    'removed_at', r.removed_at, 'removed_reason', r.removed_reason,
    'versions', (select coalesce(jsonb_agg(jsonb_build_object('version', w.version, 'saved_at', w.saved_at, 'record_md5', w.record_md5, 'bytes', w.sz,
          'record', case when w.rn <= 40 and w.cum <= 20000000 then w.record end) order by w.version), '[]'::jsonb)
      from (select v.version, v.saved_at, v.record_md5, v.record, octet_length(v.record::text) as sz,
                   row_number() over (order by v.version desc) as rn,
                   sum(octet_length(v.record::text)) over (order by v.version desc rows between unbounded preceding and current row) as cum
              from pb_prod.run_record_versions v where v.run_record_id = r.id) w),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('action', e.action, 'at', e.at, 'by', pb_prod.member_name_or_null(r.company_id, e.by_user), 'note', e.note)
          order by e.at, e.id), '[]'::jsonb)
      from pb_prod.run_record_events e where e.run_record_id = r.id),
    'setup', (select coalesce(jsonb_agg(jsonb_build_object('version', s.version, 'side', s.side, 'change', s.change, 'intended', s.intended, 'field', s.field,
          'at', s.at, 'by', pb_prod.member_name_or_null(r.company_id, s.by_user)) order by s.version, s.id), '[]'::jsonb)
      from pb_prod.run_setup_versions s where s.run_record_id = r.id));
end $f$;
revoke all on function public.pb_prod_run_versions(uuid, uuid) from public;
revoke all on function public.pb_prod_run_versions(uuid, uuid) from anon;
grant execute on function public.pb_prod_run_versions(uuid, uuid) to authenticated;

  -- ===== apply 05 (again) =====
-- records_nov22 Phase B, 05 (B8): a run's whole history for Export for Records. NEW function only; changes no table
-- and no existing function. Manager-only: the company account (owner) or a listed manager of the run's company
-- (pb_prod.managed_company, the same test the office screens use). Returns every stored version (server time, md5,
-- size), the run's events (sent back, approved, removed + reason, restored) and the office's setup changes.
-- Version records are full run records (photos are never in them; the app refuses data:image): the newest 40 versions
-- carry the record itself as long as they add up to 20 MB or less; older ones are listed with their md5 only.
-- Errors (raised, like the other run RPCs): pb:signed_out, pb:wrong_account, pb:not_found, pb:not_company_account.
-- r17.15 phones never call it. r17.16 (b8_export_versions.py) calls it from Export for Records and, on any error, says
-- so in the manifest and exports as before.
-- Independent of 01-04. Plain SQL, DO-block safe. Safe to run twice. Undo: 99_undo_05.sql.
create or replace function public.pb_prod_run_versions(p_run_id uuid, p_expect_uid uuid) returns jsonb
language plpgsql stable security definer set search_path to '' as $f$
declare v_uid uuid := auth.uid(); r pb_prod.run_records%rowtype;
begin
  if v_uid is null then raise exception 'pb:signed_out'; end if;
  if p_expect_uid is null or v_uid <> p_expect_uid then raise exception 'pb:wrong_account'; end if;
  if p_run_id is null then raise exception 'pb:not_found'; end if;
  select * into r from pb_prod.run_records x where x.id = p_run_id;
  if not found then raise exception 'pb:not_found'; end if;
  if not coalesce(pb_prod.managed_company(v_uid) = r.company_id, false) then raise exception 'pb:not_company_account'; end if;
  return jsonb_build_object('ok', true, 'run_id', r.id, 'entry_id', r.entry_id, 'current_version', r.version, 'server_at', now(),
    'removed_at', r.removed_at, 'removed_reason', r.removed_reason,
    'versions', (select coalesce(jsonb_agg(jsonb_build_object('version', w.version, 'saved_at', w.saved_at, 'record_md5', w.record_md5, 'bytes', w.sz,
          'record', case when w.rn <= 40 and w.cum <= 20000000 then w.record end) order by w.version), '[]'::jsonb)
      from (select v.version, v.saved_at, v.record_md5, v.record, octet_length(v.record::text) as sz,
                   row_number() over (order by v.version desc) as rn,
                   sum(octet_length(v.record::text)) over (order by v.version desc rows between unbounded preceding and current row) as cum
              from pb_prod.run_record_versions v where v.run_record_id = r.id) w),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('action', e.action, 'at', e.at, 'by', pb_prod.member_name_or_null(r.company_id, e.by_user), 'note', e.note)
          order by e.at, e.id), '[]'::jsonb)
      from pb_prod.run_record_events e where e.run_record_id = r.id),
    'setup', (select coalesce(jsonb_agg(jsonb_build_object('version', s.version, 'side', s.side, 'change', s.change, 'intended', s.intended, 'field', s.field,
          'at', s.at, 'by', pb_prod.member_name_or_null(r.company_id, s.by_user)) order by s.version, s.id), '[]'::jsonb)
      from pb_prod.run_setup_versions s where s.run_record_id = r.id));
end $f$;
revoke all on function public.pb_prod_run_versions(uuid, uuid) from public;
revoke all on function public.pb_prod_run_versions(uuid, uuid) from anon;
grant execute on function public.pb_prod_run_versions(uuid, uuid) to authenticated;

  -- throwaway company: owner (company account) q_ow, foreman q_fm, listed manager q_pm (pm), another company's owner q_xo
  q_tag := substr(md5(random()::text), 1, 10);
  q_ow := gen_random_uuid(); q_fm := gen_random_uuid(); q_pm := gen_random_uuid(); q_xo := gen_random_uuid();
  q_co := gen_random_uuid(); q_co2 := gen_random_uuid();
  q_day := (now() at time zone 'utc')::date - 1;
  q_b64 := replace(encode(convert_to(repeat('pbrec test photo A ', 12), 'UTF8'), 'base64'), E'\n', '');
  q_sha := encode(sha256(decode(q_b64, 'base64')), 'hex');
  q_b64b := replace(encode(convert_to(repeat('pbrec test photo B ', 12), 'UTF8'), 'base64'), E'\n', '');
  q_shab := encode(sha256(decode(q_b64b, 'base64')), 'hex');
  insert into auth.users (id, email) select u.v, 'pbrec-' || q_tag || '-' || u.o || '@example.invalid' from unnest(array[q_ow, q_fm, q_pm, q_xo]) with ordinality u(v, o);
  insert into public.companies (id, name, owner_user_id, status, plan)
    values (q_co, 'pbrec test ' || q_tag, q_ow, 'active', 'paid'), (q_co2, 'pbrec test2 ' || q_tag, q_xo, 'active', 'paid');
  insert into public.company_members (company_id, user_id, role) values (q_co, q_fm, 'foreman'), (q_co, q_pm, 'pm');
  insert into pb_reports.managers (company_id, user_id) values (q_co, q_pm) on conflict do nothing; -- live adds a PM as manager by trigger
  begin
    set local role authenticated; reset role;
    perform set_config('pbrec.as_auth', '1', true); q_notes := ' [app calls ran as role authenticated]';
  exception when others then
    perform set_config('pbrec.as_auth', '0', true); q_notes := ' [app calls ran as ' || current_user || ', not authenticated]';
  end;
  perform pg_temp.q_ck('5a pb_prod_run_versions: authenticated may call, anon and public may not',
    to_regprocedure('public.pb_prod_run_versions(uuid,uuid)') is not null and has_function_privilege('authenticated', 'public.pb_prod_run_versions(uuid,uuid)', 'execute')
    and not has_function_privilege('anon', 'public.pb_prod_run_versions(uuid,uuid)', 'execute')
    and not exists (select 1 from pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
                    where p.oid = to_regprocedure('public.pb_prod_run_versions(uuid,uuid)') and a.grantee = 0 and a.privilege_type = 'EXECUTE'), '');
  q_entry := 'q-' || q_tag || '-r1';
  q_rec := jsonb_build_object('kind', 'run', 'id', q_entry, 'jobNumber', 'Q-' || q_tag, 'lockTime', now(), 'startLabel', 'MH 1', 'endLabel', 'MH 2', 'n', 1);
  begin perform pg_temp.q_as(q_fm); q_r := public.pb_prod_run_record_put(q_entry, q_rec, q_fm, q_co); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('5b app: run record saved, version 1', q_r->>'ok' = 'true' and q_r->>'version' = '1', q_r::text);
  begin perform pg_temp.q_as(q_fm); q_r := public.pb_prod_run_record_put(q_entry, q_rec || '{"n":2}'::jsonb, q_fm, q_co); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('5c app: run record changed, version 2', q_r->>'ok' = 'true' and q_r->>'version' = '2', q_r::text);
  select r.id into q_run from pb_prod.run_records r where r.user_id = q_fm and r.entry_id = q_entry;
  insert into pb_prod.run_record_events (run_record_id, company_id, action, by_user, note) values (q_run, q_co, 'removed', q_ow, 'Duplicate run');
  insert into pb_prod.run_setup_versions (run_record_id, company_id, version, side, change, intended, by_user)
    values (q_run, q_co, 1, 'intended', '{"job_number":"Q-2"}'::jsonb, '{"job_number":"Q-2"}'::jsonb, q_pm);
  begin perform pg_temp.q_as(q_ow); q_r := public.pb_prod_run_versions(q_run, q_ow); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('5d company account: history ok, 2 versions each with its record + md5',
    q_r->>'ok' = 'true' and q_r->>'current_version' = '2' and jsonb_array_length(q_r->'versions') = 2
    and q_r->'versions'->0->>'version' = '1' and q_r->'versions'->0->'record'->>'n' = '1' and q_r->'versions'->1->'record'->>'n' = '2'
    and q_r->'versions'->1->>'record_md5' = (select r.record_md5 from pb_prod.run_records r where r.id = q_run), left(q_r::text, 300));
  perform pg_temp.q_ck('5e history has the removal with its reason and the office setup change',
    jsonb_array_length(q_r->'events') = 1 and q_r->'events'->0->>'action' = 'removed' and q_r->'events'->0->>'note' = 'Duplicate run'
    and jsonb_array_length(q_r->'setup') = 1 and q_r->'setup'->0->>'side' = 'intended', left(q_r::text, 300));
  begin perform pg_temp.q_as(q_pm); q_r := public.pb_prod_run_versions(q_run, q_pm); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('5f listed manager: history ok', q_r->>'ok' = 'true', left(q_r::text, 200));
  begin perform pg_temp.q_as(q_fm); q_r := public.pb_prod_run_versions(q_run, q_fm); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('5g the foreman who sent it: refused (manager-only)', q_r->>'err' = 'pb:not_company_account', q_r::text);
  begin perform pg_temp.q_as(q_xo); q_r := public.pb_prod_run_versions(q_run, q_xo); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('5h another company''s account: refused', q_r->>'err' = 'pb:not_company_account', q_r::text);
  begin perform pg_temp.q_as(q_ow); q_r := public.pb_prod_run_versions(q_run, q_pm); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('5i wrong account check: refused', q_r->>'err' = 'pb:wrong_account', q_r::text);
  begin perform pg_temp.q_as(null); q_r := public.pb_prod_run_versions(q_run, q_ow); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('5j signed out: refused', q_r->>'err' = 'pb:signed_out', q_r::text);
  begin perform pg_temp.q_as(q_ow); q_r := public.pb_prod_run_versions(gen_random_uuid(), q_ow); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('5k unknown run: not found', q_r->>'err' = 'pb:not_found', q_r::text);
  -- 41 more versions (43 in all): the newest 40 carry their record, the 3 oldest are listed with md5 only
  for q_i in 3..43 loop
    begin perform pg_temp.q_as(q_fm); q_r := public.pb_prod_run_record_put(q_entry, q_rec || jsonb_build_object('n', q_i), q_fm, q_co); reset role;
    exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
    exit when q_r->>'ok' is distinct from 'true';
  end loop;
  perform pg_temp.q_ck('5l app: 41 more run saves ok (version 43)', q_r->>'ok' = 'true' and q_r->>'version' = '43', q_r::text);
  begin perform pg_temp.q_as(q_ow); q_r := public.pb_prod_run_versions(q_run, q_ow); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  select count(*) filter (where v->'record' is not null and v->'record' <> 'null'::jsonb), count(*) filter (where v->>'record_md5' is not null)
    into q_n, q_m from jsonb_array_elements(coalesce(q_r->'versions', '[]'::jsonb)) v;
  perform pg_temp.q_ck('5m 43 versions listed, newest 40 with their record, all with md5',
    jsonb_array_length(q_r->'versions') = 43 and q_n = 40 and q_m = 43 and q_r->'versions'->2->'record' = 'null'::jsonb
    and q_r->'versions'->3->'record'->>'n' = '4', q_n || ' / ' || q_m);
  begin perform pg_temp.q_as(q_fm); q_r := public.pb_prod_run_record_put(q_entry, q_rec || jsonb_build_object('n', 43), q_fm, q_co); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('5n app: re-sending the same run answers same (unchanged path)', q_r->>'same' = 'true', q_r::text);
  -- SMOKE: the app paths r17.15 uses, after the change (permit open save + close-out, toolbox talk, daily report, run record)
  begin perform pg_temp.q_as(q_fm);
    q_r := public.pb_permit_open_put('cps-' || q_tag || '-s', jsonb_build_object('space', 'MH smoke', 'jobsite', 'Smoke site', 'jobNumber', 'Q-' || q_tag), q_fm); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('S1a app: open permit save (pb_permit_open_put) ok', q_r->>'ok' = 'true', q_r::text);
  begin perform pg_temp.q_as(q_fm);
    q_r := public.pb_permit_backup('cps-' || q_tag || '-s', jsonb_build_object('kind', 'confined', 'lockTime', now(), 'space', 'MH smoke', 'jobNumber', 'Q-' || q_tag), q_fm, null::text); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('S1b app: permit close-out backup (pb_permit_backup) ok, version 1', q_r->>'ok' = 'true' and q_r->>'version' = '1', q_r::text);
  perform pg_temp.q_ck('S1c app: open permit row dropped at close-out (as before)',
    not exists (select 1 from pb_safety.open_permits o where o.user_id = q_fm and o.client_permit_id = 'cps-' || q_tag || '-s'), '');
  q_id := gen_random_uuid();
  begin perform pg_temp.q_as(q_fm);
    q_r := public.pb_talk_give(q_id, 'Q-' || q_tag, 'TT-001', 'Smoke talk', q_day, null, '[{"name":"Smoke One"}]'::jsonb, false, q_fm); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('S2a app: toolbox talk save (pb_talk_give) ok', q_r->>'ok' = 'true', q_r::text);
  begin perform pg_temp.q_as(q_fm);
    q_r := public.pb_talk_give(q_id, 'Q-' || q_tag, 'TT-001', 'Smoke talk', q_day, null, '[{"name":"Smoke One"},{"name":"Smoke Two"}]'::jsonb, false, q_fm); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('S2b app: toolbox talk edit ok, version 2', q_r->>'ok' = 'true' and q_r->'talk'->>'version' = '2', q_r::text);
  begin perform pg_temp.q_as(q_fm);
    q_r := public.pb_daily_submit('q-' || q_tag || '-ds', 'Q-' || q_tag || '-S', 'Smoke site', q_day,
      '{"events":[{"kind":"delay","reason":"weather","hours":1,"cid":"s1"}]}'::jsonb, encode(sha256('smoke'::bytea), 'hex'),
      'Smoke Foreman', now(), 'America/Los_Angeles', null, null, null, now(), true, q_fm); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('S3 app: daily report save (pb_daily_submit) ok with its delay entry', q_r->>'ok' = 'true' and q_r->>'events' = '1', q_r::text);
  begin perform pg_temp.q_as(q_fm);
    q_r := public.pb_prod_run_record_put('q-' || q_tag || '-rs', jsonb_build_object('kind', 'run', 'id', 'q-' || q_tag || '-rs', 'jobNumber', 'Q-' || q_tag,
      'lockTime', now(), 'startLabel', 'MH 1', 'endLabel', 'MH 2'), q_fm, q_co); reset role;
  exception when others then q_r := jsonb_build_object('err', sqlerrm); end;
  perform pg_temp.q_ck('S4 app: run record save (pb_prod_run_record_put) ok, version 1', q_r->>'ok' = 'true' and q_r->>'version' = '1', q_r::text);
  -- ===== undo 05 =====
-- undo records_nov22 Phase B 05 (B8): drops the run history export. After this an r17.16 export just says the history
-- could not be read (the app handles the missing function). Plain SQL, DO-block safe. Safe twice.
drop function if exists public.pb_prod_run_versions(uuid, uuid);

  perform pg_temp.q_ck('5o undo 05: the function is gone', to_regprocedure('public.pb_prod_run_versions(uuid,uuid)') is null, '');
  select count(*) filter (where c.ok), count(*) filter (where c.ok is not true),
         coalesce(string_agg(c.name || ' [got: ' || coalesce(c.got, 'null') || ']', ' ; ' order by c.i) filter (where c.ok is not true), '')
    into q_pass, q_fail, q_fails from pg_temp.q_chk c;
  raise exception 'RESULT: % pass, % fail% %', q_pass, q_fail, case when q_fail > 0 then ' | FAILED: ' || q_fails else '' end, q_notes;
end $T$;
